INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('monogram-versailles-tote', 'Monogram Versailles Tote', 'Handcrafted premium bag designed with attention to durability and contemporary style.', 'Tote Bags', 16800, 21000, 20, '["https://images.unsplash.com/photo-1544816155-12df9643f363"]', '{"material":"Genuine / Vegan Leather","dimensions":"35cm x 26cm x 12cm","weight":"750g","warranty":"1 Year Islandwide Guarantee","colors":[{"name":"Classic Black","hex":"#1a1a1a"}],"features":["Premium reinforced materials","Smooth gliding heavy-duty zippers","Water-resistant protective coating","Signature Bright Buy islandwide guarantee"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('aura-luxe-italian-leather-handbag', 'Aura Luxe Italian Leather Handbag', 'Crafted from full-grain textured leather with polished gold-tone hardware. The Aura Luxe elevates everyday essentials with timeless elegance and structural precision.', 'Handbags', 18500, 24500, 15, '["https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1548036328-c9fa89d128fa?auto=format&fit=crop&w=800&q=80"]', '{"material":"Top-grain Cowhide Leather","dimensions":"32cm (L) x 24cm (H) x 12cm (W)","weight":"850g","warranty":"1 Year Manufacturer Guarantee","colors":[{"name":"Cognac Brown","hex":"#8B4513"},{"name":"Noir Black","hex":"#1a1a1a"},{"name":"Burgundy","hex":"#800020"}],"features":["Genuine full-grain Italian leather","Detachable & adjustable crossbody strap","Triple interior compartments with zip dividers","Protective metal feet at base","Signature Bright Buy dust bag included"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('metropro-urban-tech-backpack', 'MetroPro Urban Tech Backpack', 'The ultimate everyday commuter backpack engineered for tech professionals and students. Features waterproof ballistic nylon, a dedicated 16-inch padded laptop pocket, and an integrated USB charging port.', 'Backpacks', 14200, 17800, 24, '["https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1622560480605-d83c853bc5c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1546938576-6e6a64f317cc?auto=format&fit=crop&w=800&q=80"]', '{"material":"Waterproof Ballistic Nylon & TPU","dimensions":"46cm (H) x 31cm (W) x 16cm (D)","weight":"980g","capacity":"26 Liters","warranty":"2 Years Islandwide Warranty","colors":[{"name":"Stealth Charcoal","hex":"#2c3437"},{"name":"Navy Blue","hex":"#1d2d44"},{"name":"Olive Green","hex":"#3d5a45"}],"features":["Fits laptops up to 16 inches + tablet sleeve","Water-repellent 900D Oxford nylon exterior","Concealed anti-theft back pocket for passport/wallet","Ergonomic airflow back padding & chest buckle","Luggage strap for effortless travel stacking"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('riviera-canvas-leather-work-tote', 'Riviera Canvas & Leather Work Tote', 'The Riviera Tote effortlessly combines heavy-duty organic cotton canvas with premium saddle leather trim. Spacious enough for your laptop, notebook, water bottle, and makeup pouch.', 'Tote Bags', 11500, 14500, 18, '["https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1591561954557-26941169b49e?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1566150905458-1bf1fc113f0d?auto=format&fit=crop&w=800&q=80"]', '{"material":"16oz Organic Canvas + Genuine Saddle Leather","dimensions":"40cm (L) x 30cm (H) x 14cm (W)","weight":"720g","capacity":"18 Liters","warranty":"1 Year Warranty","colors":[{"name":"Cream & Tan","hex":"#e3dac9"},{"name":"Classic Black","hex":"#222222"},{"name":"Olive Canvas","hex":"#556b2f"}],"features":["Heavyweight 16oz organic canvas with leather handles","Padded laptop divider fits up to 14-inch MacBooks","Internal drink bottle holder & keychain clasp","Top zipper closure keeping belongings secure","Reinforced double-layered bottom panel"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('voyager-weekender-leather-duffle-bag', 'Voyager Weekender Leather Duffle Bag', 'Whether you are catching an island getaway to Bentota or traveling internationally, the Voyager Weekender is your ideal travel companion. Built from thick distressed crazy-horse leather with a separate shoe compartment.', 'Travel Bags', 26900, 33000, 8, '["https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1575883172638-3486be2e8e97?auto=format&fit=crop&w=800&q=80"]', '{"material":"Full-grain Distressed Cowhide Leather","dimensions":"52cm (L) x 28cm (H) x 26cm (W)","weight":"1.7kg","capacity":"42 Liters","warranty":"3 Years Islandwide Guarantee","colors":[{"name":"Vintage Antique Brown","hex":"#5c4033"},{"name":"Midnight Black","hex":"#1b1b1b"}],"features":["Independent ventilated side shoe compartment","Heavy-duty YKK antique brass zippers","Padded removable shoulder strap with non-slip pad","Meets airline cabin overhead carry-on standards","Waterproof nylon internal lining"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('celeste-quilted-crossbody-bag', 'Celeste Quilted Crossbody Bag', 'Chic chevron-quilted vegan lambskin with an intertwined gold chain strap. Lightweight yet surprisingly roomy for your phone, cardholder, lipstick, and keys.', 'Handbags', 9800, 12500, 20, '["https://images.unsplash.com/photo-1566150905458-1bf1fc113f0d?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=800&q=80"]', '{"material":"Eco-friendly Vegan Leather","dimensions":"21cm (L) x 14cm (H) x 7cm (W)","weight":"420g","warranty":"6 Months Guarantee","colors":[{"name":"Blush Pink","hex":"#ffb6c1"},{"name":"Ivory Pearl","hex":"#fffff0"},{"name":"Jet Black","hex":"#111111"}],"features":["Ultra-soft vegan lambskin with chevron diamond stitch","Convertible gold chain strap (wear long or double up)","Rotary turn-lock closure with signature Bright Buy crest","Dual interior card slots + center zippered pouch"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('kensington-executive-leather-briefcase', 'Kensington Executive Leather Briefcase', 'Tailored for the contemporary business leader. Structured vegetable-tanned leather briefcase designed with dual document compartments and a dedicated laptop sleeve.', 'Men''s Collection', 22500, 28000, 11, '["https://images.unsplash.com/photo-1548036328-c9fa89d128fa?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&w=800&q=80"]', '{"material":"Vegetable Tanned Leather","dimensions":"41cm (L) x 30cm (H) x 9cm (W)","weight":"1.3kg","warranty":"2 Years Warranty","colors":[{"name":"Oxford Tan","hex":"#a0522d"},{"name":"Espresso Dark Brown","hex":"#3b2219"},{"name":"Matte Black","hex":"#1a1a1a"}],"features":["Premium vegetable-tanned cowhide leather","Padded laptop sleeve for 15.6-inch computers","Smart trolley sleeve on back for travel ease","Detachable padded shoulder strap","Brass combination lock latch for maximum security"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('nova-anti-theft-travel-backpack', 'Nova Anti-Theft Travel Backpack', 'Engineered for peace of mind in crowded transit. Hidden zipper design, slash-proof front panel, and RFID blocking pockets ensure your valuables remain safe everywhere.', 'Backpacks', 12800, 16000, 16, '["https://images.unsplash.com/photo-1622560480605-d83c853bc5c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80"]', '{"material":"High-density Polyester & Anti-cut Kevlar Mesh","dimensions":"44cm (H) x 29cm (W) x 15cm (D)","weight":"890g","capacity":"22 Liters","warranty":"1 Year Warranty","colors":[{"name":"Space Grey","hex":"#4a4e51"},{"name":"Midnight Indigo","hex":"#1e243b"}],"features":["Concealed rear main zipper opening","Slash-resistant woven composite layers","RFID blocking passport and credit card slots","Integrated rain cover pocket at bottom","Night safety reflective striping"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('bella-soft-hobo-shoulder-bag', 'Bella Soft Hobo Shoulder Bag', 'Slouchy, effortless silhouette with comfortable wide shoulder strap. The Bella Hobo adapts effortlessly to your daily lifestyle with roomy interiors and relaxed elegance.', 'Handbags', 8900, 11900, 14, '["https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=800&q=80"]', '{"material":"Pebbled Vegan Leather","dimensions":"36cm (L) x 28cm (H) x 13cm (W)","weight":"540g","warranty":"6 Months Warranty","colors":[{"name":"Caramel Suede","hex":"#c68a4c"},{"name":"Taupe Grey","hex":"#8b8589"},{"name":"Forest Green","hex":"#2e473b"}],"features":["Plush textured vegan suede & pebbled leather","Magnetic closure with decorative side tassels","Includes matching detachable mini coin purse","Ultra-lightweight and comfortable on shoulder"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('starlight-metallic-evening-clutch', 'Starlight Metallic Evening Clutch', 'Dazzle at weddings, galas, and dinner dates. The Starlight Clutch features shimmering crystal mesh and comes with an optional drop-in chain to wear on the shoulder.', 'Wallets & Clutches', 5400, 7200, 30, '["https://images.unsplash.com/photo-1566150905458-1bf1fc113f0d?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=800&q=80"]', '{"material":"Alloy frame with crystal mesh exterior","dimensions":"20cm (L) x 11cm (H) x 5cm (W)","weight":"310g","warranty":"6 Months Guarantee","colors":[{"name":"Rose Gold","hex":"#b76e79"},{"name":"Champagne Gold","hex":"#f7e7ce"},{"name":"Silver Mirror","hex":"#c0c0c0"}],"features":["Micro-crystal glitter mesh surface","Polished metallic clasp with crystal rhinestone","Removable 120cm silver chain strap","Satin interior lining with lipstick pouch"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('heritage-trifold-rfid-leather-wallet', 'Heritage Trifold RFID Leather Wallet', 'Slim, durable, and handcrafted with certified RFID-blocking foil to protect your bank cards from wireless theft. Packed in a luxury gift box.', 'Wallets & Clutches', 3800, 4800, 45, '["https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1606503828347-1941fa70b99f?auto=format&fit=crop&w=800&q=80"]', '{"material":"Top Grain Waxed Leather","dimensions":"11.5cm (L) x 9cm (H) x 1.8cm (W)","weight":"110g","warranty":"1 Year Replacement Warranty","colors":[{"name":"Dark Tan","hex":"#7b3f00"},{"name":"Classic Black","hex":"#111111"}],"features":["100% Genuine hunter leather with contrast stitching","8 credit card slots + 2 currency bill dividers","Clear ID card window with thumb push slot","Built-in RFID blocking shield","Gift box ready packaging"]}', 1, datetime('now'), datetime('now'));
INSERT OR IGNORE INTO products (slug, name, description, category, price_lkr, compare_at_price_lkr, stock_qty, images_json, specs_json, is_active, created_at, updated_at) VALUES ('sportactive-dry-wet-gym-duffle', 'SportActive Dry-Wet Gym Duffle', 'The ultimate workout and weekend active duffle. Features a dedicated waterproof pocket for wet towels/swimwear and an isolated side sneaker tunnel.', 'Travel Bags', 7900, 9900, 22, '["https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&w=800&q=80"]', '{"material":"Ripstop 600D Waterproof Polyester","dimensions":"48cm (L) x 26cm (H) x 24cm (W)","weight":"650g","capacity":"32 Liters","warranty":"1 Year Warranty","colors":[{"name":"Coral & Grey","hex":"#ff7f50"},{"name":"Midnight Black","hex":"#202020"},{"name":"Teal Blue","hex":"#008080"}],"features":["Separate waterproof PVC wet items pocket","Breathable shoe compartment with air vent grommets","External elastic straps for holding yoga mat","Water-resistant ripstop polyester fabric"]}', 1, datetime('now'), datetime('now'));
